export const norm = s=>String(s||'').toLowerCase().replace(/[^a-z0-9 ]+/g,' ').replace(/\b(street)\b/g,'st').replace(/\broad\b/g,'rd').replace(/\bavenue\b/g,'ave').replace(/\bdrive\b/g,'dr').replace(/\bplace\b/g,'pl').replace(/\bcourt\b/g,'ct').replace(/\bcrescent\b/g,'cres').replace(/\bparade\b/g,'pde').replace(/\bterrace\b/g,'tce').replace(/\bclose\b/g,'cl').replace(/\bboulevard\b/g,'bvd').replace(/\bhighway\b/g,'hwy').replace(/\s+/g,' ').trim();
